def insertion_sort(arr: list[int]) -> list[int]:
    for i in range(1, len(arr)):
        key = arr[i]         # element to insert
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]   # shift larger elements right
            j -= 1
        arr[j + 1] = key          # place key in its sorted position
    return arr

print(insertion_sort([4, 3, 2, 10, 12, 1, 5, 6]))  # [1, 2, 3, 4, 5, 6, 10, 12]

def merge_sort(arr: list[int]) -> list[int]:
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return _merge(left, right)

def _merge(left: list[int], right: list[int]) -> list[int]:
    result: list[int] = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:    # <= preserves stability
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

print(merge_sort([38, 27, 43, 3, 9, 82, 10]))  # [3, 9, 10, 27, 38, 43, 82]

def heapsort(arr: list[int]) -> list[int]:
    n = len(arr)

    def sift_down(root: int, end: int) -> None:
        while True:
            child = 2 * root + 1          # left child
            if child >= end:
                break
            if child + 1 < end and arr[child] < arr[child + 1]:
                child += 1               # use larger child
            if arr[root] >= arr[child]:
                break
            arr[root], arr[child] = arr[child], arr[root]
            root = child

    # Phase 1: build max-heap in O(n)
    for i in range(n // 2 - 1, -1, -1):
        sift_down(i, n)

    # Phase 2: extract max n-1 times
    for end in range(n - 1, 0, -1):
        arr[0], arr[end] = arr[end], arr[0]   # move max to sorted region
        sift_down(0, end)

    return arr

print(heapsort([12, 11, 13, 5, 6, 7]))  # [5, 6, 7, 11, 12, 13]
